import glob
def is_moji(line):
    # 把行内 CJK 段按 GBK 编码回字节，若能按 UTF-8 解出多为汉字 => 双重编码
    seg=''.join(c for c in line if '\u4e00'<=c<='\u9fff' or c in '锛銆鈥�')
    if len(seg)<3: return False
    try: b=seg.encode('gbk')
    except Exception: return False
    try: d=b.decode('utf-8')
    except Exception: return False
    return sum(1 for c in d if '\u4e00'<=c<='\u9fff') >= len(d)*0.6
found=[]
for pat in ['src/**/*.h','src/**/*.cpp','tests/**/*.cpp','doc/**/*.md','AGENTS.md','TEST_RECORD.md','config/*.json','*.bat','*.json']:
    for p in glob.glob(pat, recursive=True):
        try: txt=open(p,encoding='utf-8-sig').read()
        except Exception: continue
        hits=[i+1 for i,l in enumerate(txt.splitlines()) if is_moji(l)]
        if hits: found.append((p,len(hits),hits[:8]))
print('=== 严格判定：双重编码损坏文件 ===')
print('无' if not found else '')
for f in found: print(f)
